raw = lzma.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(raw).hexdigest() == "21b74d4d64caea0eeeb88ea073e6ff549620194bd3c6114e3c77dfc2ffafaca5"
data = json.loads(raw)
with tempfile.TemporaryDirectory(prefix="monitor-bundle-") as directory:
    root = pathlib.Path(directory)
    (root / "edits.json").write_text(json.dumps(data["manifest"]))
    (root / "apply.py").write_text(data["apply"])
    for relative, contents in data["new"].items():
        destination = root / "new-files" / relative
        if not destination.resolve().is_relative_to(root.resolve()):
            raise ValueError("Unsafe source path")
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(contents)
    subprocess.run([sys.executable, str(root / "apply.py"), sys.argv[1], "--apply"], check=True)
